import { createStorage, StorageEnum } from '../base/index.js';
const storage = createStorage('theme-storage-key', {
    theme: 'system',
    isLight: getSystemTheme(),
}, {
    storageEnum: StorageEnum.Local,
    liveUpdate: true,
});
// Функция для определения системной темы
function getSystemTheme() {
    if (typeof window !== 'undefined' && window.matchMedia) {
        return window.matchMedia('(prefers-color-scheme: light)').matches;
    }
    return true; // По умолчанию светлая тема
}
export const exampleThemeStorage = {
    ...storage,
    toggle: async () => {
        await storage.set(currentState => {
            let newTheme;
            switch (currentState.theme) {
                case 'light':
                    newTheme = 'dark';
                    break;
                case 'dark':
                    newTheme = 'system';
                    break;
                case 'system':
                default:
                    newTheme = 'light';
                    break;
            }
            const isLight = newTheme === 'system' ? getSystemTheme() : newTheme === 'light';
            return {
                theme: newTheme,
                isLight,
            };
        });
    },
};
